import React from 'react';
import { Link } from 'react-router-dom';
import { UserGroupIcon } from '@heroicons/react/24/outline';

const MatchesPage = () => {
  return (
    <div className="min-h-screen bg-neutral-50">
      <div className="container mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="max-w-6xl mx-auto">
          <div className="card">
            <div className="text-center py-12">
              <UserGroupIcon className="w-16 h-16 text-neutral-400 mx-auto mb-4" />
              <h1 className="text-h2 mb-2">Matches Page</h1>
              <p className="text-neutral-600 mb-6">
                Match management and viewing features will be implemented here.
              </p>
              <div className="flex space-x-4 justify-center">
                <Link to="/dashboard" className="btn btn-primary">
                  Back to Dashboard
                </Link>
                <Link to="/discover" className="btn btn-outline">
                  Find More Matches
                </Link>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default MatchesPage;
